// Demonstration data was replaced by the live catalog: live-catalog.js fills it from /api/catalog. Tests split app.js at this line.
let catalog = [];
// A language detected earlier in this session is known before /api/locale answers (Italian loads later, in italian.js).
let lang = translations[window.MobialoLocale?.current] ? window.MobialoLocale.current : 'en';

let activeTab = 'local';
let expanded = false;
let query = '';
let selectedDestination = null;
let selectedPlan = 1;
let modalView = null;
let suggestionIndex = -1;
let suggestions = [];
const $ = selector => document.querySelector(selector);
const t = key => translations[lang][key];
const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const currencyFormats = {};
const currencyFormat = (locale, currency) => currencyFormats[locale + currency] ??= new Intl.NumberFormat(locale, {style:'currency',currency});
const money = value => currencyFormat(lang==='it'?'it-IT':lang === 'sq' ? 'sq-AL' : 'en-IE', 'EUR').format(value);
// A country without a plan of its own shows its cheapest regional plan, labelled as such.
const fromText = item => t(item.regionalPrice ? 'fromRegional' : 'from');
// Prefix matches in the current language first, then word prefixes in any language, then any substring.
function searchRank(item, term) {
  if (normalize(item[lang] || '').startsWith(term)) return 0;
  const names = normalize(`${item.en} ${item.sq} ${item.it || ''} ${item.aliases || ''}`);
  return names.split(/[^a-z0-9]+/).some(word => word.startsWith(term)) ? 1 : names.includes(term) ? 2 : -1;
}
const searchMatches = term => catalog.map((item, index) => ({item, index, rank: searchRank(item, term)})).filter(match => match.rank >= 0).sort((a, b) => a.rank - b.rank || a.index - b.index).map(match => match.item);
const plansFor = destination => destination.plans || [];
// Placeholders with the cards' own box keep the grid at its final height until the catalog arrives (also in index.html).
const skeletonCards = () => '<div class="destination-card skeleton" aria-hidden="true"><span class="flag"></span><div><h3><i></i></h3><p><i></i></p></div></div>'.repeat(9);
function flag(destination) {
  return `<span class="flag" aria-hidden="true">${destination.symbol || `<img src="https://flagcdn.com/w80/${destination.id}.png" alt="" loading="lazy">`}</span>`;
}
function closeSuggestions() {
  $('#search-suggestions').hidden = true;
  $('#search').setAttribute('aria-expanded', 'false');
  $('#search').removeAttribute('aria-activedescendant');
  suggestionIndex = -1;
}
function renderSuggestions() {
  const term = normalize(query);
  suggestions = term ? searchMatches(term) : [];
  suggestionIndex = -1;
  const list = $('#search-suggestions');
  list.innerHTML = suggestions.length ? suggestions.map(item => `<div role="option" aria-selected="false" id="suggestion-${item.id}" data-suggestion="${item.id}" class="search-option">${flag(item)}<span><strong>${item[lang]}</strong><small>${(lang==='it'?"Vedi tutti i piani":lang === 'sq' ? 'Shiko të gjitha paketat' : 'View all plans')}</small></span><span class="suggestion-price">${fromText(item)} ${money(item.price)}<span aria-hidden="true">→</span></span></div>`).join('') : `<div class="search-empty">${t('noResults')}</div>`;
  list.hidden = !term;
  list.setAttribute('aria-label', t('searching'));
  $('#search').setAttribute('aria-expanded', String(!!term));
  $('#search').removeAttribute('aria-activedescendant');
  $('#search-announcement').textContent = term ? `${suggestions.length} ${t('results')}` : '';
}
function chooseDestination(item) {
  if (!item) return;
  selectedDestination = item;
  selectedPlan = 0;
  query = item[lang];
  $('#search').value = query;
  renderCatalog();
  closeSuggestions();
  openModal('plans');
}
function renderCatalog() {
  const term = normalize(query);
  const filtered = term ? searchMatches(term) : catalog.filter(item => item.type === activeTab);
  const visible = expanded || term ? filtered : filtered.slice(0,9);
  const loading = !catalog.length;
  // Only a list longer than the first nine scrolls inside the panel.
  $('#destination-grid').classList.toggle('is-scroll', visible.length > 9);
  $('#destination-grid').innerHTML = visible.length ? visible.map(item => `<button class="destination-card" data-destination="${item.id}">${flag(item)}<div><h3>${item[lang]}</h3><p>${fromText(item)} <b>${money(item.price)}</b></p></div><span class="card-arrow" aria-hidden="true">→</span></button>`).join('') : loading ? skeletonCards() : `<div class="empty-state"><p>${t('noResults')}</p><button class="button outline" id="clear-search">${t('clearSearch')}</button></div>`;
  $('#results-status').textContent = term ? `${filtered.length} ${t('results')}` : '';
  // While the catalog loads the button keeps its place, invisible, so nothing below it moves.
  $('#show-all').hidden = !loading && (!!term || filtered.length <= 9);
  $('#show-all').style.display = $('#show-all').hidden ? 'none' : '';
  $('#show-all').style.visibility = loading ? 'hidden' : '';
  $('#show-all').innerHTML = t(expanded ? 'fewerDestinations' : 'allDestinations');
  document.querySelectorAll('[data-tab]').forEach(button => {
    const selected = !term && button.dataset.tab === activeTab;
    button.classList.toggle('active', selected);
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex = selected || (term && button.dataset.tab === activeTab) ? 0 : -1;
  });
  const grid = $('#destination-grid');
  if (term) {grid.removeAttribute('aria-labelledby');grid.setAttribute('aria-label',t('searching'));}
  else {grid.removeAttribute('aria-label');grid.setAttribute('aria-labelledby',`tab-${activeTab}`);}
}
function setLanguage(value) {
  lang = value;
  document.documentElement.lang = lang;
  if($('.journey-stamp'))$('.journey-stamp').innerHTML=(lang==='en'?'EUROPE':'EUROPA')+'<br><b>↗</b><br>MOBIALO';
  if($('.city-photo span'))$('.city-photo span').textContent=lang==='it'?'PARIGI, FRANCIA':lang==='sq'?'PARIS, FRANCË':'PARIS, FRANCE';
  window.MobialoLocale.syncSelect($('#language'),lang);
  document.title = t('pageTitle');
  document.querySelector('meta[name="description"]').content = t('metaDescription');
  document.querySelectorAll('[data-i18n]').forEach(element => element.innerHTML = t(element.dataset.i18n));
  // The destination count comes from the live catalog, never from a fixed number.
  const destinationCount = catalog.filter(item => item.type === 'local').length;
  // The prefix stays the same as before the catalog arrived; only the count is added after it.
  if (destinationCount) $('.hero [data-i18n="eyebrow"]').innerHTML = `${t('eyebrow')}<span class="eyebrow-count">${t('eyebrowCount').replace('{n}', destinationCount)}</span>`;
  $('.trust-row').setAttribute('aria-label', t('trustLabel'));
  document.querySelectorAll('[data-placeholder]').forEach(element => {element.placeholder = t(element.dataset.placeholder);element.setAttribute('aria-label',t(element.dataset.placeholder));});
  $('#search-form button').setAttribute('aria-label',t('search'));
  $('#close-modal').setAttribute('aria-label',t('close'));
  $('#language').setAttribute('aria-label',(lang==='it'?"Lingua":lang === 'sq' ? 'Gjuha' : 'Language'));
  $('nav').setAttribute('aria-label',(lang==='it'?"Navigazione principale":lang === 'sq' ? 'Navigimi kryesor' : 'Main navigation'));
  $('.tabs').setAttribute('aria-label',(lang==='it'?"Tipo di piano":lang === 'sq' ? 'Lloji i paketës' : 'Plan type'));
  $('.benefit-strip').setAttribute('aria-label',(lang==='it'?"Vantaggi eSIM":lang === 'sq' ? 'Përfitimet e eSIM' : 'eSIM benefits'));
  $('.travel-photo img').alt = (lang==='it'?"Edifici bianchi affacciati sul mare blu a Santorini":lang === 'sq' ? 'Ndërtesa të bardha mbi detin blu në Santorini' : 'White hillside buildings overlooking the blue sea in Santorini');
  $('.city-photo img').alt = (lang==='it'?"I tetti di Parigi e la Torre Eiffel":lang === 'sq' ? 'Çatitë e Parisit dhe Kulla Eifel' : 'Paris rooftops and the Eiffel Tower');
  const openFaq = [...document.querySelectorAll('#faq-list details')].map(item => item.open);
  $('#faq-list').innerHTML = t('faq').map(([question,answer],index) => `<details${openFaq[index] ? ' open' : ''}><summary>${question}</summary><p>${answer}</p></details>`).join('');
  renderCatalog();
  closeSuggestions();
  if (modalView) renderModal();
  // index.html starts hidden (html.lang-pending) when its static English may not be the visitor's language.
  if (value === window.MobialoLocale?.current && window.MobialoLocale.settled) document.documentElement.classList.remove('lang-pending');
}
function switchTab(type) {
  activeTab = type;
  query = '';
  $('#search').value = '';
  expanded = false;
  renderCatalog();
  closeSuggestions();
}
function scrollToCatalog() {$('#destinations').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'});}
function renderModal() {
  const content = $('#modal-content');
  $('#modal').classList.toggle('device-dialog', modalView === 'device');
  if (modalView === 'device') {
    content.innerHTML = `<div class="modal-eyebrow">MOBIALO · eSIM</div><h2 id="modal-title">${t('deviceTitle')}</h2><p class="modal-subtitle">${t('deviceIntro')}</p><label class="device-search-label" for="device-search">${(lang==='it'?"Cerca il modello del telefono":lang === 'sq' ? 'Kërko modelin e telefonit' : 'Search your phone model')}</label><input id="device-search" class="device-search" type="search" placeholder="iPhone 15, Galaxy S24, Pixel 9..." autocomplete="off"><p class="device-updated">${lang==='it'?'Modelli selezionati · Verificato il 16 ottobre 2026':lang === 'sq' ? 'Modele të përzgjedhura · Kontrolluar më 16 tetor 2026' : 'Selected models · Checked 16 October 2026'}</p><div id="device-results">${deviceListMarkup()}</div><h3 class="device-check-heading">${(lang==='it'?"Prima di acquistare":lang === 'sq' ? 'Para se të blesh' : 'Before you buy')}</h3><ol class="guide-list">${t('deviceSteps').map(step => `<li>${step}</li>`).join('')}</ol><p class="modal-note">${t('deviceNote')}</p><button class="button modal-action" data-close>${t('gotIt')}</button>`;
  } else if (modalView === 'plans') {
    content.innerHTML = `<div class="modal-eyebrow">${t('demoPrices')}</div><div class="modal-heading">${flag(selectedDestination)}<h2 id="modal-title">${selectedDestination[lang]} eSIM</h2></div><p class="modal-subtitle">${t('choosePlan')}</p><div class="plan-list" role="radiogroup" aria-label="${t('choosePlan')}">${plansFor(selectedDestination).map((plan,index) => `<label class="plan-option"><input type="radio" name="plan" value="${index}" ${index === selectedPlan ? 'checked' : ''}><span><strong>${plan.gb} GB</strong><small>${plan.days} ${t('days')} · ${t('dataOnly')}</small></span><b>${money(plan.price)}</b></label>`).join('')}</div><p class="modal-note">${t('planNote')}</p><button class="button modal-action" id="review-plan">${t('review')} →</button>`;
  } else {
    const plan = plansFor(selectedDestination)[selectedPlan];
    content.innerHTML = `<div class="modal-eyebrow">${t('demoPrices')}</div><h2 id="modal-title">${t('reviewTitle')}</h2><p class="modal-subtitle">${t('reviewIntro')}</p><div class="review-row"><span>${t('destination')}</span><strong>${selectedDestination[lang]}</strong></div><div class="review-row"><span>${t('data')}</span><strong>${plan.gb} GB</strong></div><div class="review-row"><span>${t('duration')}</span><strong>${plan.days} ${t('days')}</strong></div><div class="review-row"><span>${t('total')}</span><strong>${money(plan.price)}</strong></div><p class="modal-note">${t('notLive')}</p><button class="button modal-action" disabled>${t('checkout')}</button><button class="text-link" style="margin-top:18px" id="back-to-plans">${t('back')}</button>`;
  }
  $('#modal').setAttribute('aria-labelledby','modal-title');
}
// The title takes focus, as in the back/review handlers, so the close button shows no focus ring on open.
function openModal(view) {modalView = view;renderModal();$('#modal').showModal();const title = $('#modal-title');if (title) {title.tabIndex = -1;title.focus({preventScroll:true});}}
$('#language').addEventListener('change', event => {window.MobialoLocale.choose(event.target.value);setLanguage(event.target.value);});
const searchBox = document.createElement('div');
searchBox.className = 'search-box';
$('#search-form').before(searchBox);
searchBox.append($('#search-form'));
const searchList = document.createElement('div');
searchList.id = 'search-suggestions';
searchList.className = 'search-suggestions';
searchList.setAttribute('role', 'listbox');
searchList.hidden = true;
searchBox.append(searchList);
const searchAnnouncement = document.createElement('span');
searchAnnouncement.id = 'search-announcement';
searchAnnouncement.className = 'visually-hidden';
searchAnnouncement.setAttribute('role', 'status');
searchBox.append(searchAnnouncement);
$('#search').setAttribute('role', 'combobox');
$('#search').setAttribute('aria-autocomplete', 'list');
$('#search').setAttribute('aria-controls', 'search-suggestions');
$('#search').setAttribute('aria-expanded', 'false');
$('#search-form').addEventListener('submit', event => {
  event.preventDefault();
  query = $('#search').value;
  const chosen = suggestionIndex >= 0 ? suggestions[suggestionIndex] : suggestions.length === 1 ? suggestions[0] : null;
  if (chosen) chooseDestination(chosen);
  else {renderCatalog();renderSuggestions();$('#search').focus();}
});
$('#search').addEventListener('input', event => {query = event.target.value;renderCatalog();renderSuggestions();});
$('#search').addEventListener('focus', () => {query = $('#search').value;renderSuggestions();});
$('#search').addEventListener('keydown', event => {
  if (event.key === 'Escape') {closeSuggestions();return;}
  if (!['ArrowDown', 'ArrowUp'].includes(event.key)) return;
  event.preventDefault();
  if (searchList.hidden) renderSuggestions();
  if (!suggestions.length) return;
  suggestionIndex = (suggestionIndex + (event.key === 'ArrowDown' ? 1 : suggestionIndex < 0 ? 0 : -1) + suggestions.length) % suggestions.length;
  searchList.querySelectorAll('[role=option]').forEach((option, index) => option.setAttribute('aria-selected', String(index === suggestionIndex)));
  const option = $(`#suggestion-${suggestions[suggestionIndex].id}`);
  $('#search').setAttribute('aria-activedescendant', option.id);
  option.scrollIntoView({block:'nearest'});
});
searchList.addEventListener('mousedown', event => event.preventDefault());
searchList.addEventListener('click', event => {
  const option = event.target.closest('[data-suggestion]');
  if (option) chooseDestination(catalog.find(item => item.id === option.dataset.suggestion));
});
document.addEventListener('pointerdown', event => {if (!searchBox.contains(event.target)) closeSuggestions();});
searchBox.addEventListener('focusout', event => {if (!searchBox.contains(event.relatedTarget)) closeSuggestions();});
document.querySelectorAll('[data-search]').forEach(button => button.addEventListener('click', () => {
  chooseDestination(catalog.find(item => item.en === button.dataset.search));
}));
document.querySelectorAll('[data-tab]').forEach(button => button.addEventListener('click', () => switchTab(button.dataset.tab)));
$('.tabs').addEventListener('keydown', event => {
  if (!['ArrowRight','ArrowLeft','Home','End'].includes(event.key)) return;
  event.preventDefault();
  const tabs = [...document.querySelectorAll('[data-tab]')];
  const current = tabs.indexOf(document.activeElement);
  const index = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
  switchTab(tabs[index].dataset.tab);tabs[index].focus();
});
$('#show-all').addEventListener('click', () => {expanded = !expanded;renderCatalog();});
$('#explore-regional').addEventListener('click', () => {switchTab('regional');scrollToCatalog();});
$('#destination-grid').addEventListener('click', event => {
  const card = event.target.closest('[data-destination]');
  if (card) {selectedDestination = catalog.find(item => item.id === card.dataset.destination);selectedPlan = 1;openModal('plans');}
  if (event.target.closest('#clear-search')) {query = '';$('#search').value = '';renderCatalog();}
});
['#compatibility','#compatibility-footer','#footer-device','#how-device'].forEach(selector => $(selector).addEventListener('click', () => openModal('device')));
$('#close-modal').addEventListener('click', () => $('#modal').close());
$('#modal').addEventListener('close', () => {if(!$('#modal').open)modalView = null;});
$('#modal').addEventListener('click', event => {
  if (event.target === $('#modal')) {const bounds = $('#modal').getBoundingClientRect();if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) $('#modal').close();}
  if (event.target.closest('[data-close]')) $('#modal').close();
  if (event.target.closest('#review-plan')) {modalView = 'review';renderModal();$('#modal-title').tabIndex = -1;$('#modal-title').focus();}
  if (event.target.closest('#back-to-plans')) {modalView = 'plans';renderModal();$('#modal-title').tabIndex = -1;$('#modal-title').focus();}
});
$('#modal-content').addEventListener('change', event => {if (event.target.name === 'plan') selectedPlan = Number(event.target.value);});
// The header's primary button (#destinations without JavaScript) brings the destination search into view.
$('.header-actions .button').addEventListener('click', event => {event.preventDefault();$('#search').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'});$('#search').focus({preventScroll:true});});
setLanguage(lang);

$('#modal-content').addEventListener('input', event => {if (event.target.id === 'device-search') $('#device-results').innerHTML = deviceListMarkup(event.target.value);});
